@walk_programs : ∀ {Rate Cap : Type} [inst : AddCommGroup Rate] {O : Oracle (Rate × Cap) (Rate × Cap)}
  {iv s : Rate × Cap},
  O.lookup s = none →
    ∀ {m : List Rate}, completion? O iv s = some m → ∀ (v : Rate × Cap), walkFrom (O.respond s v).2 iv m = some v
@sponge_realizes_handler_step : ∀ {Rate Cap : Type} [inst : AddCommGroup Rate] (iv : Rate × Cap)
  (ro : Oracle (List Rate) Rate) (os : Oracle (Rate × Cap) (Rate × Cap)) {s : Rate × Cap},
  os.lookup s = none →
    ∀ {m : List Rate},
      completion? os iv s = some m →
        ∀ (rc rc' : Rate) (bc : Rate × Cap),
          walkFrom (simFwdRO iv ro os s rc bc).2.2 iv m = some ((ro.respond m rc).1, bc.2) ∧
            ((simFwdRO iv ro os s rc bc).2.1.respond m rc').1 = (ro.respond m rc).1
@uniquePaths_simFwd : ∀ {Rate Cap : Type} [inst : AddCommGroup Rate] {O : Oracle (Rate × Cap) (Rate × Cap)}
  {iv s coin : Rate × Cap},
  UniquePaths O iv →
    ∀ (H : List Rate → Rate), coin.2 ∉ capsOf O iv → coin.2 ≠ s.2 → UniquePaths (simFwd H iv O s coin).2 iv
@capBad_le : ∀ {Cap : Type} [inst : Fintype Cap] (qc : ℕ) (S : Finset Cap),
  S.card ≤ qc + 1 → uniformProb (Fin qc → Cap) (CapBad S) ≤ 2 * ↑qc ^ 2 / ↑(Fintype.card Cap)
